#Code to generate discordant pair plots corresponding to Figure 6 and Supplemental Figure 4
#Input files required: TSV files generated by bash scripts (get_rec_rates.sh) containing recombination count data
#Expected files in working directory: *_Bob2_Car_recombination_counts.tsv, *_Bob2_Bill_recombination_counts.tsv, *_Car_Bill_recombination_counts.tsv, *_Bob2_CCS4_recombination_counts.tsv

library(ggplot2)
library(stringr)
library(dplyr)

setwd("/mnt/d/Research/WhitesonCollab/Data/recombination_rate")

filelist = dir(pattern='Bob2_Car')
bobcardf = read.csv(filelist[1], header=T, sep='\t')
for(i in 2:length(filelist)){
	bobcardf = rbind(bobcardf, read.csv(filelist[i], header=T, sep='\t'))
}

bobcardf$drop = 0
bobcardf$drop[bobcardf$Sample=='S2M'&bobcardf$Time=='5']=1  #We will exclude S2M Time 5 as it is a very strange outlier that might be overstating an the prevalence of an artifact in the alignment.

filelist = dir(pattern='Bob2_Bill')
bobbilldf = read.csv(filelist[1], header=T, sep='\t')
for(i in 2:length(filelist)){
	bobbilldf = rbind(bobbilldf, read.csv(filelist[i], header=T, sep='\t'))
}

bobbilldf$drop = 0
bobbilldf$drop[bobbilldf$Sample=='S2M'&bobbilldf$Time=='5']=1

filelist = dir(pattern='Car_Bill')
carbilldf = read.csv(filelist[1], header=T, sep='\t')
for(i in 2:length(filelist)){
	carbilldf = rbind(carbilldf, read.csv(filelist[i], header=T, sep='\t'))
}

carbilldf$drop = 0
carbilldf$drop[carbilldf$Sample=='S2M'&carbilldf$Time=='5']=1

filelist = dir(pattern='Bob2_CCS4')
bobccs4df = read.csv(filelist[1], header=T, sep='\t')
for(i in 2:length(filelist)){
	bobccs4df = rbind(bobccs4df, read.csv(filelist[i], header=T, sep='\t'))
}

bobcardf$DiscordFreq = bobcardf$DiscordantCount/(bobcardf$TotalReads)
bobbilldf$DiscordFreq = bobbilldf$DiscordantCount/(bobbilldf$TotalReads)
carbilldf$DiscordFreq = carbilldf$DiscordantCount/(carbilldf$TotalReads)
bobccs4df$DiscordFreq = bobccs4df$DiscordantCount/(bobccs4df$TotalReads)

bobcardf$pair = 'Bob-Car'
bobbilldf$pair = 'Bob-Bill'
carbilldf$pair = 'Car-Bill'
bobccs4df$pair = 'Bob-CCS4'

columnset = c('pair','Sample','Time','SplitCount','DiscordantCount','TotalReads','DiscordFreq')
allrecdf = rbind(bobcardf[,columnset], bobbilldf[,columnset])
allrecdf = rbind(allrecdf, carbilldf[,columnset])
allrecdf = rbind(allrecdf, bobccs4df[,columnset])

#Drop S2M at t5
allrecdf$drop = 0
allrecdf$drop[allrecdf$Sample=='S2M' & allrecdf$Time == 5] = 1
allrecdf = subset(allrecdf, drop==0)

#Fix cousin T20 names (artifact of how the files were originally set up locally)
allrecdf$Sample = str_replace(allrecdf$Sample, '_T20', '')
allrecdf = allrecdf[-which(is.na(allrecdf$DiscordFreq)),]  #some values are NA if there were no events. E.g. Bob-CCS4 at Time 20

#Exclude the ancestors from the summary plot
#Update Sample labels for manuscript nomenclature
allrecdf$Sample = str_replace(allrecdf$Sample, 'Sisters', 'Similar')
allrecdf$Sample = str_replace(allrecdf$Sample, 'Cousins', 'Dissimilar')
allrecdf$Sample = str_replace(allrecdf$Sample, 'C', 'D')
allrecdf$Sample = str_replace(allrecdf$Sample, 'I', 'P')
allrecdf$Sample = factor(allrecdf$Sample, levels = c('Phage_Similar_R1','Phage_Similar_R2','Phage_Similar_R3',
													 'Phage_Dissimilar_R1','Phage_Dissimilar_R2','Phage_Dissimilar_R3',
													 'S1M','S2M','S3M','S1P','S2P','S3P',
													 'D1M','D2M','D3M','D1P','D2P','D3P'))
colrange = brewer.pal(9, 'Set1')
col_fun = c(
	'Phage_Similar_R1' = colrange[9],
	'Phage_Similar_R2' = colrange[9],
	'Phage_Similar_R3' = colrange[9],
	'Phage_Dissimilar_R1' = colrange[9],
	'Phage_Dissimilar_R2' = colrange[9],
	'Phage_Dissimilar_R3' = colrange[9],
	'S1M' = colrange[1],
	'S2M' = colrange[2],
	'S3M' = colrange[3],
	'S1P' = colrange[4],
	'S2P' = colrange[5],
	'S3P' = colrange[7],
	'D1M' = colrange[1],
	'D2M' = colrange[2],
	'D3M' = colrange[3],
	'D1P' = colrange[4],
	'D2P' = colrange[5],
	'D3P' = colrange[7]
)

col_fun_alt = c(
	'Similar_t0' = colrange[9],
	'Dissimilar_t0' = colrange[9],
	'S1M' = colrange[1],
	'S2M' = colrange[2],
	'S3M' = colrange[3],
	'S1P' = colrange[4],
	'S2P' = colrange[5],
	'S3P' = colrange[7],
	'D1M' = colrange[1],
	'D2M' = colrange[2],
	'D3M' = colrange[3],
	'D1P' = colrange[4],
	'D2P' = colrange[5],
	'D3P' = colrange[7]
)
#counts for supplement. Frequencies for main text

#Set the sample ID for the t0 to just "t0"
allrecdf$SampleAlt = as.character(allrecdf$Sample)
allrecdf$SampleAlt = str_replace(allrecdf$SampleAlt, 'Phage_Similar_R[123]', 'Similar_t0')
allrecdf$SampleAlt = str_replace(allrecdf$SampleAlt, 'Phage_Dissimilar_R[123]', 'Dissimilar_t0')
allrecdf$SampleAlt = factor(allrecdf$SampleAlt, levels = c('Similar_t0','Dissimilar_t0','S1M','S2M','S3M','S1P','S2P','S3P','D1M','D2M','D3M','D1P','D2P','D3P'))

disc_plot_sibs_count = ggplot(subset(allrecdf, pair!='Bob-CCS4' & Time!='ancestor'), aes(x=as.numeric(Time), y=DiscordantCount, color=SampleAlt)) +
	facet_wrap(vars(pair), scales='free')+
	geom_line()+
	geom_point()+
	xlab('Cycle')+
	ylab('Total Discordant Pairs')+
	labs(color = 'Sample')+
	guides(color = guide_legend(nrow = 3))+
	scale_color_manual(values = col_fun_alt, breaks = c('S1M','S2M','S3M','S1P','S2P','S3P','Similar_t0'))+
	xlab('Time')+
	theme_bw() + theme(text = element_text(face='bold', size=8), legend.position = 'bottom')

disc_plot_sibs_freq = ggplot(subset(allrecdf, pair!='Bob-CCS4' & Time!='ancestor'), aes(x=as.numeric(Time), y=DiscordFreq, color=SampleAlt)) +
	facet_wrap(vars(pair), scales='free')+
	geom_line()+
	geom_point()+
	xlab('Cycle')+
	ylab('Total Discordant Pairs')+
	labs(color = 'Sample')+
	guides(color = guide_legend(nrow = 3))+
	scale_color_manual(values = col_fun_alt, breaks = c('S1M','S2M','S3M','S1P','S2P','S3P','Similar_t0'))+
	xlab('Time')+
	theme_bw()+ theme(text = element_text(face='bold', size=8), legend.position = 'bottom')
	
disc_plot_cousins_count = ggplot(subset(allrecdf, pair=='Bob-CCS4' & Time!='ancestor'), aes(x=as.numeric(Time), y=DiscordantCount, color=SampleAlt)) +
	facet_wrap(vars(pair))+
	geom_line()+
	geom_point()+
	xlab('Cycle')+
	ylab('Total Discordant Pairs')+
	labs(color = 'Sample')+
	guides(color = guide_legend(nrow = 3))+
	scale_color_manual(values = col_fun_alt, breaks = c('D1M','D2M','D3M','D1P','D2P','D3P','Dissimilar_t0'))+
	xlab('Time')+
	theme_bw()+ theme(text = element_text(face='bold', size=8), legend.position = 'bottom')

disc_plot_cousins_freq = ggplot(subset(allrecdf, pair=='Bob-CCS4' & Time!='ancestor'), aes(x=as.numeric(Time), y=DiscordFreq, color=SampleAlt)) +
	facet_wrap(vars(pair))+
	geom_line()+
	geom_point()+
	xlab('Cycle')+
	ylab('Total Discordant Pairs')+
	labs(color = 'Sample')+
	guides(color = guide_legend(nrow = 3))+
	scale_color_manual(values = col_fun_alt, breaks = c('D1M','D2M','D3M','D1P','D2P','D3P','Dissimilar_t0'))+
	xlab('Time')+
	theme_bw()+ theme(text = element_text(face='bold', size=8), legend.position = 'bottom')

#Save plots
png('../discord_freq_sim.png', height=400, width=800)
print(disc_plot_sibs_freq)
dev.off()

png('../discord_count_sim.png', height=400, width=800)
print(disc_plot_sibs_count)
dev.off()

png('../discord_freq_diss.png', height=500, width=400)
print(disc_plot_cousins_freq)
dev.off()

png('../discord_count_diss.png', height=500, width=400)
print(disc_plot_cousins_count)
dev.off()

pdf('../discord_freq_sim.pdf', height=4, width=4.5)
print(disc_plot_sibs_freq)
dev.off()

pdf('../discord_count_sim.pdf', height=4, width=4.5)
print(disc_plot_sibs_count)
dev.off()

pdf('../discord_freq_diss.pdf', height=5, width=3.25)
print(disc_plot_cousins_freq + theme(plot.margin = margin(5,15,5,5, 'mm')))
dev.off()

pdf('../discord_count_diss.pdf', height=5, width=3.25)
print(disc_plot_cousins_count + theme(plot.margin = margin(5,15,5,5, 'mm')))
dev.off()

