disc_plot_cousins_freq2 = ggplot(subset(allrecdf, pair=='Bob-CCS4' & Time!='ancestor'), aes(x=as.numeric(Time), y=DiscordFreq, color=SampleAlt)) +
	facet_wrap(vars(pair))+
