#Plot discordant locations
samplelist = c('S1M','S2M','S3M','S1I','S2I','S3I')
timelist = paste0('t',c(1,2,3,4,5,10,15,20))
samplelist2 = c('C1M','C2M','C3M','C1I','C2I','C3I')

setwd("/mnt/d/Research/WhitesonCollab/Data/RawReads/sisters_t1")

#Note: the files are longer than some previous steps and the for loops below will be a bit slow.
rec.df = read.table(paste0(samplelist[1],"_Bob2_Car_recombinant_discordant_depth.txt")) %>% mutate(sample=samplelist[1], time = 't1')
for(i in 2:length(samplelist)){
	temp = read.table(paste0(samplelist[i],"_Bob2_Car_recombinant_discordant_depth.txt")) %>% mutate(sample=samplelist[i], time = 't1')
	rec.df = rbind(rec.df, temp)
}
for(i in 2:length(timelist)){
	setwd(paste0("../sisters_",timelist[i]))
	for(j in 1:length(samplelist)){
		temp = read.table(paste0(samplelist[j],"_Bob2_Car_recombinant_discordant_depth.txt")) %>% mutate(sample=samplelist[j], time = timelist[i])
	rec.df = rbind(rec.df, temp)
	}
}

colnames(rec.df)[1:3] = c('contig','position','depth')
rec.df$ID = paste0(rec.df$sample, '_', rec.df$time)
idorder = character()
for(i in 1:length(samplelist)){for(j in 1:length(timelist)){
idorder = c(idorder, paste0(samplelist[i],'_',timelist[j]))}}
rec.df$ID = factor(rec.df$ID, levels=idorder)
rec.df$sample = factor(rec.df$sample, levels=samplelist)
rec.df$time = factor(rec.df$time, levels = timelist)

rec.df$RelDepth = 0
for(i in 1:length(samplelist)){
	for(j in 1:length(timelist)){
		temp = which(rec.df$sample == samplelist[i] & rec.df$time == timelist[j])
		rec.df$RelDepth[temp] = rec.df$depth[temp]/max(rec.df$depth[temp])
	}
}

#Prior to plotting, we need to re-orient the positions to match the layout in other manuscript figures, which begins from the terminase genes. We follow the same steps as used in mutation_plots.txt. #These steps assume that mutation_plots has been run and the objects tempgtf_bob, newgtf_car, and tempgtf_ccs4 are still available in the workspace, as well as nbob, ncar, and nccs4.
bobdf = subset(rec.df, contig == 'Bob2')
cardf = subset(rec.df, contig == 'Car')

#Bob
termgene = grep('terminase', tempgtf_bob$product)[1]
termstart = tempgtf_bob$start[termgene]
bobdf$NewPosition = 0
bobdf$NewPosition[bobdf$position >= termstart] = bobdf$position[bobdf$position >= termstart] - termstart + 1
bobdf$NewPosition[bobdf$position < termstart] = nbob - (termstart - bobdf$position[bobdf$position < termstart])

#Car
cardf$NewPosition = ncar - cardf$position + 1 #This should reverse the values to match the first step in newgtf_car
termgene = grep('terminase', newgtf_car$product)[1]
termstart = newgtf_car$start2[termgene]  #use start2 to match the reversed start values
cardf$NewPosition2 = 0
cardf$NewPosition2[cardf$NewPosition >= termstart] = cardf$NewPosition[cardf$NewPosition >= termstart] - termstart + 1
cardf$NewPosition2[cardf$NewPosition < termstart] = ncar - (termstart - cardf$NewPosition[cardf$NewPosition < termstart])
cardf$NewPosition = cardf$NewPosition2 #update so that we can have the same columns when rbind-ing each df back to rec.df

rec.df = rbind(bobdf, cardf[,colnames(bobdf)])
rec.df$sample = as.character(rec.df$sample)
rec.df$sample = str_replace(rec.df$sample, 'I', 'P')
rec.df$sample = factor(rec.df$sample, levels = c('S1M','S2M','S3M','S1P','S2P','S3P'))
rec_pos_sibs_bob = ggplot(subset(rec.df, contig=='Bob2'), aes(x=NewPosition, y=time, color=log10(depth), alpha=depth, size=depth))+
	facet_wrap(vars(sample), ncol=1, strip.position = 'right')+
	geom_point()+
	ylab('Cycle')+
	xlab('Position')+
	scale_color_gradient2(low='white', mid='darkblue', high='red', midpoint=1)+
	scale_alpha_continuous(range=c(0,1))+
	scale_size_continuous(range=c(0,2))+
	theme_bw()+theme(text=element_text(size=8))

rec_pos_sibs_car = ggplot(subset(rec.df, contig=='Car'), aes(x=NewPosition, y=time, color=log10(depth), alpha=depth, size=depth))+
	facet_wrap(vars(sample), ncol=1, strip.position = 'right')+
	geom_point()+
	ylab('Cycle')+
	xlab('Position')+
	scale_color_gradient2(low='white', mid='darkblue', high='red', midpoint=1)+
	scale_alpha_continuous(range=c(0,1))+
	scale_size_continuous(range=c(0,2))+
	theme_bw()+theme(text=element_text(size=8))

pdf('../../discordant_positions_sim_bob_narrow.pdf', height=5.5, width=3.75)
print(rec_pos_sibs_bob)
dev.off()

pdf('../../discordant_positions_sim_car_narrow.pdf', height=5.5, width=3.75)
print(rec_pos_sibs_car)
dev.off()

