# Aligning discordant pairs to their respective genome maps (Figure 6C)
netplot <- function(pair_coords, ref1, ref2, gtf1=tempgtf_bob, gtf2=newgtf_car, n1=nbob, n2=ncar, reorder = TRUE){
	colnames(pair_coords) = c('y_start','x_start','y_end','x_end')
	
	# if reorder == TRUE, need to correct the positions using the provided gtfs. Note: only set up for Bob and Car
	if(reorder == TRUE){
		termgene1 = grep('terminase', gtf1$product)[1]
		termstart1 = gtf1$start[termgene1]
		pair_coords$new_x_start = 0
		pair_coords$new_x_start[pair_coords$x_start >= termstart1] = pair_coords$x_start[pair_coords$x_start >= termstart1] - termstart1 + 1
		pair_coords$new_x_start[pair_coords$x_start < termstart1] = n1 - (termstart1 - pair_coords$x_start[pair_coords$x_start < termstart1])

		pair_coords$new_x_end = n2 - pair_coords$x_end + 1 #This should reverse the values to match the first step in newgtf_car
		termgene2 = grep('terminase', gtf2$product)[1]
		termstart2 = gtf2$start2[termgene2]  #use start2 to match the reversed start values
		pair_coords$new_x_end2 = 0
		pair_coords$new_x_end2[pair_coords$new_x_end >= termstart2] = pair_coords$new_x_end[pair_coords$new_x_end >= termstart2] - termstart2 + 1
		pair_coords$new_x_end2[pair_coords$new_x_end < termstart2] = n2 - (termstart2 - pair_coords$new_x_end[pair_coords$new_x_end < termstart2])
		
		#finally, reset the original positions to the new values so the plot is always the same setup
		pair_coords$x_start = pair_coords$new_x_start
		pair_coords$x_end = pair_coords$new_x_end2
	}		
	
	results = list()
	results$pair_coords = pair_coords
	results$plot = ggplot(pair_coords, aes(x=x_start, y=y_start, xend=x_end, yend=y_end))+
		geom_segment(linewidth = 0.1, alpha = 0.1)+
		scale_y_discrete(limits = c(ref2, ref1))+
		theme_bw()
	return(results)
}

